out={'status':'REVIEW DRAFT — NOT APPROVED','sources':[{'path':str(p.relative_to(ROOT)),'sha256':sha(p)} for p in inputs],'unit':'Biology Grade 10 · Chemicals of Life · source sub-strand 1.2','lessons':6,'scheduled_minutes':480,'pending':['Science and source-owner review','Native PowerPoint, Slide Show and Presenter View','Teacher approval','Practical safety and equipment decisions','ARES content and offline access','Calibri fidelity']}
