    resources=[];seen=set()
    for ph,values in lesson['resourceLinks'].items():
        for item in values.values():
            if isinstance(item,dict) and item.get('direct_url') and item['direct_url'] not in seen:
                seen.add(item['direct_url']);resources.append('- '+item['title']+' — Preview first; match, content, offline availability and spoiler risk unverified. '+item['direct_url'])
